public static long maxOperationsOnGraph(int N, int M, int[] u, int[] v, int[] W, long[] A) {
    long operations = 0;
    boolean piecesLeft = true;

    while (piecesLeft) {
        piecesLeft = false;
        for (int i = 0; i < N; i++) {
            if (A[i] > 0) {
                piecesLeft = true;
                A[i]--;

                long sumWeights = 0;
                for (int j = 0; j < M; j++) {
                    if (u[j] == i) {
                        sumWeights += W[v[j]];
                    } else if (v[j] == i) {
                        sumWeights += W[u[j]];
                    }
                }

                if (sumWeights < W[i]) {
                    for (int j = 0; j < M; j++) {
                        if (u[j] == i) {
                            A[v[j]]++;
                        } else if (v[j] == i) {
                            A[u[j]]++;
                        }
                    }
                    operations++;
                }
            }
        }
    }

    return operations;
}
